/** @param {{des: object}} api */
export default function bigrm_13({ des, selection, math, luaList, luaLen }) {
    des.level_init({ style: 'solidfill', fg: ' ' });
    des.level_flags('mazelevel', 'noflip');

    des.map(`---------------------------------------------------------------------------
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
---------------------------------------------------------------------------
`);

    const pillar = `---
| |
---`;

    // luaList keeps Lua's 1-based indices, so filters[n] means the same here.
    const filters = luaList(
        // 1: all pillars
        (x, y) => {
            return true;
        },
        // 2: 3 vertical lines
        (x, y) => {
            return (x % 2 === 1);
        },
        // 3: checkerboard
        (x, y) => {
            return (((x + y) % 2) === 0);
        },
        // 4: center row
        (x, y) => {
            return (y % 2 === 1);
        },
        // 5: top and bottom rows
        (x, y) => {
            return (y % 2 === 0);
        },
        // 6: random 50%
        (x, y) => {
            return (math.random(0, 1) === 0);
        },
        // 7: corners and center
        (x, y) => {
            return ((x / 3) % 2 === y % 2);
        },
        // 8: slanted
        (x, y) => {
            return (Math.floor((x + 1) / 3) === y);
        },
    );

    const idx = math.random(1, luaLen(filters));

    for (let y = 0; y <= 2; y++) {
        for (let x = 0; x <= 6; x++) {
            if (filters[idx](x, y)) {
                des.map({ coord: [12 + x * 9, 4 + y * 5], map: pillar, contents: () => {} });
            }
        }
    }

    des.region(selection.area(0, 0, 75, 18), 'lit');
    des.wallify();
    des.non_diggable();

    des.stair('up');
    des.stair('down');

    for (let i = 1; i <= 15; i++) {
        des.object();
    }
    for (let i = 1; i <= 6; i++) {
        des.trap();
    }
    for (let i = 1; i <= 28; i++) {
        des.monster();
    }
}
